(() => {
  const C = window.CURTAIN_CONTENT;
  const add = (id, title, subtitle, lead, source, sections) => {
    const chapters = sections.map(([heading, ...paragraphs]) => ({ heading, paragraphs }));
    C.articles.push({ id, section:'people', eyebrow:'人物档案 / 公开资料', title, subtitle, lead, source, chapters, paragraphs:chapters.flatMap(c => c.paragraphs) });
  };
  add('crotty-family-study','克罗蒂：一个姓氏的重量','家族传承与个人命运','研究一个古老家族，需要同时看见它积累的知识、建立的权势，以及继承这些遗产的人。',['克罗蒂家族','十九家','庭代尔·克罗蒂'],[
    ['古老的家族','克罗蒂家族与卡莫瑞亚的贵族史密切相关，后世把它与摩伊拉、德维雷斯并称为“上三族”。这个名称指向历史地位，并不意味着三家在所有时代都拥有一致的政治立场。','长期保存的魔法知识、造物和家族关系，可以使一个家族在世代更替之后仍然保持影响。对克罗蒂而言，支配魔法尤其是理解其传承和政治关系的重要线索。'],
    ['名望与争议','家族势力的成长，并不是只有财富和名望的历史。克罗蒂在漫长的政治活动中树立过许多敌人；关于它如何行使权力，留存的评价也并不一致。','家族的力量可能被视为地方秩序的保障，也可能被视为对他人意志的威胁。阅读家族史时，需要留意记录者所处的位置，而不能只接受赞颂或指控中的一种。'],
    ['传承给下一代','到了庭代尔和提亚纳斯成长的时代，古老的姓氏仍然具有分量，家族本身却已不复昔日兴盛。两兄弟成长于同一家族，也各自形成了不同的性格与经历。','一份家族档案可以说明他们继承了什么，却不能单凭继承解释他们后来作出的每一个选择。']]);
  add('tiarnas-early-study','提亚纳斯·克罗蒂','在书页与兄长的目光中长大','提亚纳斯的早年，既属于一座古老家族的书房，也属于他与哥哥之间紧密的关系。',['提亚纳斯·克罗蒂','圣德赛尔'],[
    ['家庭与成长','提亚纳斯生于1951年的卡莫瑞亚，是庭代尔的亲弟弟。他大约八岁时失去父母，之后与哥哥及家里的管家共同生活。','父母留下的空缺没有使他与庭代尔之间形成简单的长幼关系。对年幼的提亚纳斯来说，哥哥既是家人，也是他认识力量和安全感的重要参照。'],
    ['家族的书房','庭代尔前往圣德赛尔就读期间，年幼的提亚纳斯留在家中，阅读克罗蒂先辈留下的典籍。他从这些记载中认识家族的聪明、勇敢、开创性和强烈的自信。','家族史向他展示了许多值得仰望的名字，而庭代尔在他心中的位置仍然特殊。理解他的早年，需要同时看见对先辈的认同和对兄长的依恋。'],
    ['学院中的学生','提亚纳斯后来也进入圣德赛尔学习。现有记载称他表现出色，学业范围广泛，其中包括庭代尔并不擅长的魔法史。','关于学院的完整学制、校址和组织关系，现存资料仍不足以重建。人物的求学经历可以确认，但不能据此推定所有制度细节。']]);
  add('sinclair-study','辛克莱尔·德维雷斯','裁决执行处与一个古老家族','辛克莱尔的身份跨越了两种政治传统：贵族家族的世代传承，以及联合部的公共职务。',['辛克莱尔','十九家','魔法联合部'],[
    ['德维雷斯的传承','辛克莱尔出身德维雷斯家族。这个古老家族的历史与契约、证言和裁决密切相关；在贵族政治中，被不同争端各方接受的仲裁本身就是一种重要的权力。','能够判断证言与契约的人，既可能为社会提供解决争端的程序，也可能借此获得影响。讨论德维雷斯的政治传统，不能只看到这两面中的一面。'],
    ['公共职位','辛克莱尔担任魔法联合部裁决执行处处长，是一位拥有“真实”权柄的资深半神。现存资料记载，他与自己的家族关系疏远。','他的经历提醒我们，出身不能自动等同于政治立场。公共机构成员可能受过家族传统的教育，却仍然需要在个人职责、机构权威和家族关系之间作出判断。'],
    ['姓名之外','一位身居公职的施法者，既是个人，也是制度的一部分。研究辛克莱尔时，与其把他简单归入某个家族的代言人，不如考察联合部的执行权如何与旧有贵族资源交织。']]);
  add('knights-community','诺伐圣廷骑士团','六位成员与一段共同生活','骑士团不仅是一个由强大施法者组成的团体，也是一群来自不同背景的人所形成的关系网络。',['骑士团','庭代尔·克罗蒂'],[
    ['成员与导师','庭代尔亲自挑选并教导骑士团成员。公开的六席依次为厄尼西姆、加利贝尔、普里多尼、赫法恩斯、塞浦路斯与切西娅；他们来自不同族群，具有不同的能力和经历。','席次提供了一种方便辨认的顺序，却无法代替对每个人的了解。研究他们之间的关系，既要看战斗能力，也要看日常生活中的照顾、信任与争执。'],
    ['不以血缘为基础的家庭','在早期相处的岁月里，庭代尔既是领导者，也是导师和大家长。厄尼西姆与加利贝尔常以兄长、姐姐的角色照看其他成员。','这并非没有摩擦的共同体。不同性格的人相处时会打闹、较劲，也会互相照顾。正是这些细节，让骑士团不仅是历史记载中的一列名字。'],
    ['各自带来的传统','赛特斯族的渡厄神官、翼人族的审判者、质人族的炼金实践者和半羊人族的梦境研究者，将不同的经验带到同一处。成员的背景并不因为共同的组织身份而消失。','将骑士团作为关系网络来观察，可以看到个人如何被共同生活改变，同时继续保有来自各自出身与经历的问题。']]);
  add('ernicium-profile','厄尼西姆','沉默的首席','在骑士团的记忆中，厄尼西姆是少言的兄长，也是照看其他成员的人。',['厄尼西姆','骑士团'],[
    ['来自赛特斯族','厄尼西姆来自赛特斯族。关于这一海岛族群的记载，将对死亡的信仰与对生命的珍视同时放在重要位置。理解他的经历，需要看见这两个并存的方面。','他曾担任渡厄神官。相关力量与至亲寿命的代价相联系，这一传统让他对力量及其代价有切身认识。'],
    ['追随与选择','厄尼西姆追随庭代尔，其中一个愿望是改变族人面对的“以命换命”的困境。这不是对死亡的简单恐惧，而是对一种需要亲人付出代价的生活方式的回应。','他的经历表明，同样拥有强大力量的人，对力量可能持有截然不同的期待：有人希望借它取得权势，也有人希望用它摆脱代价。'],
    ['作为兄长','作为骑士团首席，厄尼西姆与加利贝尔共同照看弟弟妹妹们。他通常沉默、憨厚，但寡言之下也有不易察觉的狡黠。','关于成员相处的记载中，他偶尔会在弟弟妹妹打闹时透露行踪。这样的日常片段，为理解一位常被称作“首席”的人提供了另一种尺度。']]);
  add('galibel-profile','加利贝尔','对公平的执着','加利贝尔是骑士团的次席，也是在成员之间主持公道的姐姐。',['加利贝尔','骑士团'],[
    ['童年的经验','加利贝尔出身翼人族。她在童年因家庭对性别的偏见受到忽视，这段经历与她后来对公平的执着密切相关。','公平对她而言并非抽象口号。被区别对待的经验，使她格外关注谁有机会说话、谁又被忽略。'],
    ['骑士团中的姐姐','在骑士团中，加利贝尔与厄尼西姆一起承担照看其他成员的责任。她平时直率，遇事行动迅速，也很维护自己认定的家人。','当弟弟妹妹之间发生争执时，她习惯主持公道。既亲近成员又坚持判断，是她在共同生活中承担的重要位置。'],
    ['审判与公平','加利贝尔与“审判”权柄相联系。研究这一称号时，有必要把它与她的成长经历及处事方式放在一起：审判不仅涉及力量，也涉及如何看待他人与他们的处境。']]);
  add('huffines-profile','赫法恩斯','研究梦境的人','第四席赫法恩斯的故事，为理解梦境如何连接人与记忆提供了一个入口。',['赫法恩斯','骑士团'],[
    ['梦境与观察','赫法恩斯出身半羊人族，与“幻梦”权柄相联系。现存记载强调他对梦境和情报的运用，也描述了他通常冷静、克制的举止。','梦境可能呈现人们在清醒时掩藏的情绪和愿望。长期接触这些内容，使观察者面对的不仅是力量问题，也有如何理解他人、保护自己的问题。'],
    ['平静的外表','他在外表上常显得疏离，但这种平静不必被理解成缺乏感情。资料将他的性格描述为外冷内热；保持距离与关心他人，有时会同时存在。','在骑士团成员的共同生活中，他与其他成员既有亲近也有分歧。一份只列出能力的档案，无法完整呈现这些关系。'],
    ['研究方法的边界','有关梦境的记录往往依赖个人视角。梦中看见的事物、做梦者的情绪与现实中的行动之间，不能未经辨析便画上等号。对赫法恩斯的研究，也需要区分能力的表现和观察者对其意图的解释。']]);
  add('pridony-profile','普里多尼','物质与炼金的研究者','骑士团第三席普里多尼的经历，使个人信念与物质研究产生了紧密联系。',['普里多尼','骑士团','炼金术'],[
    ['质人族与物质','普里多尼出身质人族。现有资料将这一族群与对物质的亲和及炼金实践联系起来；其知识传统不能简单等同于巫师后来分化出的学科分类。','炼金术在不同群体中的传承方式、工具与术语存在差异。即便最终效果相近，研究过程也可能并不相同。'],
    ['精密的力量','普里多尼与“物质”权柄相联系，其能力涉及对物质结构的改变。对他的记录尤其突出操作的精密程度，以及将研究用于实际场合的能力。','对一种力量的描述，应同时考察它能够做到什么、需要怎样的理解，以及它在具体情境中如何被使用。'],
    ['信念与追随','早期记载中的普里多尼对自身能力十分自信。与庭代尔相遇后，他对后者产生了强烈认同，成为骑士团的追随者。','他对导师的忠诚也是理解其人物关系的重要线索，但一段关系的意义不能仅用“强者追随更强者”来概括。']]);
  add('cyprus-profile','塞浦路斯','时间与珍视之物','塞浦路斯是骑士团的第五席；关于他，资料同时记载了时间研究与日常生活中的细节。',['塞浦路斯','骑士团'],[
    ['出身与性格','塞浦路斯是星中人混血，其父亲为人类。记录中他有蓝色头发，十分珍视感情，却有时以在意面子的姿态遮掩自己的真实想法。','他的出身与人际关系都提醒研究者：一种族群身份并不能解释一个人的全部。具体的家庭经历和相处方式同样重要。'],
    ['关于刹那','塞浦路斯与“刹那”权柄相关。有关能力的记载区分了观察尚未抵达现实的未来，与改变已经发生的过去；两者不能被直接混为一谈。','观察的时间跨度和反复尝试都会对施法者造成负担。研究时间类魔法时，能力的边界与代价应当和效果一起讨论。'],
    ['一块星纱','骑士团的日常记录中，塞浦路斯曾偷偷试戴切西娅的星纱，又担心别人嘲笑自己的装饰。这个片段呈现出他对美的喜爱，也暴露出他对他人评价的在意。','与重大的政治事件相比，这件小事更容易让读者看见成员之间熟悉、打闹的关系。']]);
  add('chessia-profile','切西娅','欲望、情绪与归属','切西娅是骑士团的末席。她的档案关乎情绪与欲望，也关乎对被接纳的渴望。',['切西娅','骑士团'],[
    ['早年的家庭','切西娅出身月人族。现有资料记载，她的原生家庭充满争吵和冲突，情感上的缺失深刻影响了她对亲密关系的期待。','理解这些经历，不意味着将她此后的每一次选择都归结为童年；它提供的是理解其防备与需求的一条线索。'],
    ['与庭代尔相遇','庭代尔注意到年轻的切西娅，后来将她带在身边。与过去的家庭生活相比，这段经历使她感受到一种此前少有的照顾和安全感。','骑士团并非由血缘组成，但成员间常以家人彼此称呼。对切西娅而言，这种归属感具有特殊意义。'],
    ['欲望与情绪','切西娅与“欲望”权柄相联系，擅长情绪及精神方面的干涉。研究欲望魔法时，研究者需要区别个人原有的愿望与外部力量对情绪的影响。','对于个体来说，欲望不只有危险的一面：被理解、被爱和获得安全同样可能构成人的需要。这些不同层次，使切西娅的研究不应只停留在能力的分类上。']]);
})();
